/**
 * Cloudflare Workers entry (CR-002). Serves the OpenNext build of the app and
 * runs the every-minute Cron Trigger that replaces vercel.json's crons and the
 * in-process scheduler (lib/cron/scheduler.ts), which cannot run on Workers.
 *
 * The cron calls the app's own routes through the same fetch handler, so the
 * work runs inside a normal Next.js request (per-request database client, auth
 * checks unchanged).
 */
// @ts-expect-error: generated by `opennextjs-cloudflare build`.
import { default as handler } from "../.open-next/worker.js";

type Env = { CRON_SECRET?: string; AUTH_URL?: string; NEXTAUTH_URL?: string; [key: string]: unknown };

type Ctx = { waitUntil(promise: Promise<unknown>): void; passThroughOnException?(): void };

const CRON_ROUTES = ["/api/internal/cron", "/api/v1/webhooks/dispatch"];

function appOrigin(env: Env): string {
  for (const candidate of [env.AUTH_URL, env.NEXTAUTH_URL]) {
    if (!candidate) continue;
    try {
      return new URL(candidate).origin;
    } catch {
      // Try the next one.
    }
  }
  return "https://ziki-finance.ibuild-ai.workers.dev";
}

async function runCronRoutes(env: Env, ctx: Ctx): Promise<void> {
  if (!env.CRON_SECRET) {
    console.warn("[cron] CRON_SECRET is not set; skipping scheduled sweeps.");
    return;
  }
  const origin = appOrigin(env);
  // One after the other: the Free plan allows 10 ms of CPU per invocation.
  for (const path of CRON_ROUTES) {
    try {
      const response: Response = await handler.fetch(
        new Request(`${origin}${path}`, {
          method: "POST",
          headers: { authorization: `Bearer ${env.CRON_SECRET}` },
        }),
        env,
        ctx,
      );
      if (!response.ok) console.warn(`[cron] ${path} returned ${response.status}`);
    } catch (err) {
      console.error(`[cron] ${path} failed`, err);
    }
  }
}

export default {
  fetch: handler.fetch,
  async scheduled(_event: unknown, env: Env, ctx: Ctx) {
    ctx.waitUntil(runCronRoutes(env, ctx));
  },
};
